{
  "name": "伪时钟时钟线",
  "name_en": "Pseudoclock Clock Line",
  "manufacturer": "",
  "description": "伪时钟实验时序系统中的时钟输出线或时钟通道，用于向下游设备分发定时脉冲，协调数字量、模拟量等实验序列的同步运行。",
  "description_en": "A clock output line or channel in a pseudoclock-based experimental timing system. It distributes timing pulses to downstream devices and synchronizes digital, analog, and other time-sequenced laboratory operations.",
  "tag_hints": [
    "pseudoclock timing",
    "clock pulse distribution",
    "experiment synchronization",
    "digital and analog sequencing",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-add_device",
      "description": "将下游设备接入该时钟线。",
      "description_en": "Attach a downstream device to this clock line."
    },
    {
      "action_name": "auto-clock_limit",
      "description": "获取该时钟线的时钟频率上限。",
      "description_en": "Get the clock frequency limit of this clock line."
    },
    {
      "action_name": "auto-minimum_clock_high_time",
      "description": "获取该时钟线时钟脉冲的最小高电平持续时间。",
      "description_en": "Get the minimum high-state duration of the clock pulses on this clock line."
    },
    {
      "action_name": "auto-collect_change_times",
      "description": "收集该时钟线上各输出需要变化的时间点。",
      "description_en": "Collect the times at which outputs on this clock line must change."
    },
    {
      "action_name": "auto-expand_change_times",
      "description": "将变化时间点展开为该时钟线的详细时序事件。",
      "description_en": "Expand change times into detailed timing events for this clock line."
    },
    {
      "action_name": "auto-get_outputs_by_clockline",
      "description": "获取由该时钟线驱动的输出通道。",
      "description_en": "Get the output channels driven by this clock line."
    },
    {
      "action_name": "auto-generate_clock",
      "description": "为该时钟线生成时钟脉冲序列。",
      "description_en": "Generate the clock pulse sequence for this clock line."
    },
    {
      "action_name": "auto-generate_code",
      "description": "生成该时钟线对应的时序控制代码。",
      "description_en": "Generate the timing control code for this clock line."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发该时钟线所属的时序开始运行。",
      "description_en": "Trigger the timing sequence associated with this clock line."
    },
    {
      "action_name": "auto-do_checks",
      "description": "执行该时钟线的配置与时序检查。",
      "description_en": "Perform configuration and timing checks for this clock line."
    },
    {
      "action_name": "auto-is_master_pseudoclock",
      "description": "判断该时钟线所属时序源是否为主伪时钟。",
      "description_en": "Determine whether the timing source associated with this clock line is the master pseudoclock."
    },
    {
      "action_name": "auto-set_initial_trigger_time",
      "description": "设置该时钟线的初始触发时间。",
      "description_en": "Set the initial trigger time for this clock line."
    },
    {
      "action_name": "auto-offset_instructions_from_trigger",
      "description": "按触发时间对该时钟线的时序指令进行偏移。",
      "description_en": "Offset this clock line's timing instructions relative to the trigger time."
    }
  ]
}

